def vram_by_phase(path):
    """memory.used MiB per phase, parsed from the vram.txt section headers."""
    if not path.exists():
        return None
    sections = {}
    current = None
    for line in path.read_text().splitlines():
        line = line.strip()
        if line.startswith("== "):
            current = line[len("== "):.split("(")][0].strip() if False else line.split("== ", 1)[1].split("(")[0].strip()
            sections.setdefault(current, [])
        elif current is not None and re.search(r"\b(\d+) MiB,", line):
            sections[current].append(int(re.search(r"\b(\d+) MiB,", line).group(1)))
    return {k: (statistics.median(v) if v else None) for k, v in sections.items()}

